css:
.exec-sim-container {
    padding: 28px;
    background: #f4f5f7;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1a2744;
}

.exec-sim-container * {
    box-sizing: border-box;
}

.exec-sim-header {
    background: #1a2744;
    color: #f4f5f7;
    padding: 32px 36px;
    border-radius: 4px;
    margin-bottom: 20px;
    border-left: 6px solid #c9a14a;
    position: relative;
    overflow: hidden;
}

.exec-sim-header::after {
    content: '';
    position: absolute;
    top: 0; right: 0; bottom: 0;
    width: 220px;
    background: linear-gradient(135deg, transparent 0%, rgba(201,161,74,0.08) 100%);
    pointer-events: none;
}

.exec-sim-eyebrow {
    color: #c9a14a;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 700;
}

.exec-sim-header h1 {
    margin: 0;
    font-size: 1.85rem;
    font-weight: 700;
    color: #ffffff;
    letter-spacing: -0.01em;
    line-height: 1.2;
}

.exec-sim-subtitle {
    margin: 10px 0 0 0;
    color: rgba(255,255,255,0.72);
    font-size: 0.95rem;
    font-weight: 400;
}

.exec-sim-meta {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #ffffff;
    border: 1px solid #e2e5ea;
    padding: 14px 22px;
    border-radius: 4px;
    margin-bottom: 20px;
    font-size: 0.85rem;
    color: #5a6172;
    font-weight: 500;
}

.exec-sim-meta .exec-sim-clock {
    margin-left: auto;
    background: #c9a14a;
    color: #1a2744;
    padding: 5px 14px;
    border-radius: 4px;
    font-weight: 700;
    font-size: 0.75rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.exec-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 22px;
}

.exec-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #e2e5ea;
    border-radius: 4px;
    padding: 18px 20px;
    border-top: 3px solid #1a2744;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.exec-sim-kpi-card:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(26,39,68,0.06);
}

.exec-sim-kpi-card--accent {
    border-top-color: #c9a14a;
    background: linear-gradient(180deg, #fdfaf2 0%, #ffffff 60%);
}

.exec-sim-kpi-label {
    font-size: 0.7rem;
    color: #5a6172;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 700;
}

.exec-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #1a2744;
    font-variant-numeric: tabular-nums;
    line-height: 1;
}

.exec-sim-kpi-card--accent .exec-sim-kpi-value {
    color: #846829;
}

.exec-sim-briefing {
    background: #ffffff;
    border: 1px solid #e2e5ea;
    border-left: 4px solid #1a2744;
    border-radius: 4px;
    padding: 22px 28px;
    margin-bottom: 20px;
}

.exec-sim-briefing-title {
    font-size: 1rem;
    font-weight: 700;
    color: #1a2744;
    margin-bottom: 10px;
    letter-spacing: 0.01em;
}

.exec-sim-briefing-body {
    color: #3d4759;
    font-size: 0.93rem;
    line-height: 1.6;
}

.exec-sim-controls {
    background: #ffffff;
    border: 1px solid #e2e5ea;
    border-radius: 4px;
    padding: 26px 28px;
    margin-bottom: 20px;
}

.exec-sim-controls h3 {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #5a6172;
    margin: 0 0 20px 0;
    font-weight: 700;
}

.exec-sim-field {
    margin-bottom: 18px;
}

.exec-sim-field label {
    display: block;
    font-size: 0.83rem;
    font-weight: 600;
    color: #1a2744;
    margin-bottom: 6px;
}

.exec-sim-controls input[type="number"],
.exec-sim-controls input[type="text"],
.exec-sim-controls select {
    width: 100%;
    background: #ffffff;
    border: 1px solid #c8cdd6;
    border-radius: 4px;
    padding: 10px 12px;
    color: #1a2744;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.exec-sim-controls select option {
    background: #ffffff;
    color: #1a2744;
}

.exec-sim-controls select:focus,
.exec-sim-controls input:focus {
    outline: none;
    border-color: #1a2744;
    box-shadow: 0 0 0 3px rgba(26,39,68,0.1);
}

.exec-sim-controls .btn {
    border-radius: 4px;
    padding: 11px 24px;
    font-weight: 600;
    font-size: 0.9rem;
    letter-spacing: 0.02em;
    border: 1px solid transparent;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease;
    margin-top: 6px;
}

.exec-sim-controls .btn-primary {
    background: #1a2744;
    border-color: #1a2744;
    color: #ffffff;
}

.exec-sim-controls .btn-primary:hover {
    background: #2c3a5e;
    border-color: #2c3a5e;
}

.exec-sim-controls .btn-outline-secondary {
    background: transparent;
    border: 1px solid #c8cdd6;
    color: #5a6172;
    margin-left: 8px;
}

.exec-sim-controls .btn-outline-secondary:hover {
    background: #f4f5f7;
    color: #1a2744;
}

.exec-sim-feedback {
    background: #fdfaf2;
    border: 1px solid #e8d9ad;
    border-left: 4px solid #c9a14a;
    border-radius: 4px;
    padding: 18px 22px;
    margin-bottom: 20px;
}

.exec-sim-feedback-title {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #846829;
    font-weight: 700;
    margin-bottom: 10px;
}

.exec-sim-feedback-body {
    color: #3d4759;
    font-size: 0.92rem;
    line-height: 1.65;
}

.exec-sim-history {
    background: #ffffff;
    border: 1px solid #e2e5ea;
    border-radius: 4px;
    padding: 22px 26px;
    margin-bottom: 20px;
}

.exec-sim-history h3 {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #5a6172;
    margin: 0 0 14px 0;
    font-weight: 700;
}

.exec-sim-history table {
    width: 100%;
    font-size: 0.88rem;
    border-collapse: collapse;
}

.exec-sim-history table th {
    background: #f4f5f7;
    color: #1a2744;
    font-weight: 700;
    font-size: 0.72rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    padding: 10px 12px;
    border-bottom: 2px solid #1a2744;
    text-align: left;
}

.exec-sim-history table td {
    padding: 10px 12px;
    border-bottom: 1px solid #ecedef;
    color: #3d4759;
    vertical-align: top;
}

.exec-sim-chart-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
    margin-bottom: 24px;
}

.exec-sim-chart-card {
    background: #ffffff;
    border: 1px solid #e2e5ea;
    border-radius: 4px;
    padding: 20px 22px;
    height: 320px;
    display: flex;
    flex-direction: column;
}

.exec-sim-chart-card h4 {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #5a6172;
    margin: 0 0 14px 0;
    font-weight: 700;
}

.exec-sim-chart-card canvas {
    flex: 1;
    min-height: 0;
}

@media (max-width: 768px) {
    .exec-sim-container { padding: 16px; }
    .exec-sim-header { padding: 22px 20px; }
    .exec-sim-header h1 { font-size: 1.4rem; }
    .exec-sim-chart-grid { grid-template-columns: 1fr; }
    .exec-sim-meta { flex-wrap: wrap; }
    .exec-sim-meta .exec-sim-clock { margin-left: 0; margin-top: 6px; }
    .exec-sim-kpi-value { font-size: 1.6rem; }
    .exec-sim-controls { padding: 20px; }
    .exec-sim-briefing { padding: 18px 20px; }
}
/* --- v1.1.0 accessibility + debrief ------------------------------------ */
.exec-sim-container .exec-button-row { display: block; }
.exec-sim-container button:focus-visible,
.exec-sim-container select:focus-visible,
.exec-sim-container input:focus-visible {
    outline: 3px solid #1f2a44;
    outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
    .exec-sim-container *, .exec-sim-container *::before, .exec-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
    }
}
.exec-debrief {
    background: #ffffff; color: #1f2a44; border-radius: 6px;
    padding: 22px 24px; margin-bottom: 20px; border-left: 5px solid #876c30;
}
.exec-debrief h3 { margin: 0 0 12px 0; font-size: 1.05rem; letter-spacing: 0.06em; text-transform: uppercase; }
.exec-debrief-headline, .exec-debrief-outcome { font-size: 1.02rem; margin-bottom: 8px; }
.exec-debrief-insights p { margin: 8px 0; }

