        validateDecisions(decisions) {
            var st = window.mySimulation.state;
            this._updateBriefing(st);
            var round = st.currentPeriod;

            if (round === 1) {
                var sf = document.getElementById('sentenceFramingInput');
                if (sf) decisions.sentenceFraming = sf.value;
                var fc = document.getElementById('forkClarityInput');
                if (fc) decisions.forkClarity = fc.value;
                var kl = document.getElementById('killListSizeInput');
                if (kl) decisions.killListSize = kl.value;
            } else if (round === 2) {
                var sh = document.getElementById('slideHeadlinesInput');
                if (sh) decisions.slideHeadlines = sh.value;
                var bd = document.getElementById('bodyDensityInput');
                if (bd) decisions.bodyDensity = bd.value;
                var ap = document.getElementById('askPlacementInput');
                if (ap) decisions.askPlacement = ap.value;
            } else if (round === 3) {
                var os = document.getElementById('openingStyleInput');
                if (os) decisions.openingStyle = os.value;
                var tp = document.getElementById('timingPlanInput');
                if (tp) decisions.timingPlan = tp.value;
                var ap2 = document.getElementById('askPhrasingInput');
                if (ap2) decisions.askPhrasing = ap2.value;
                var ib = document.getElementById('interruptionBridgesInput');
                if (ib) decisions.interruptionBridges = ib.value;
            }
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod;
            var d = state.decisions;
            var round = state.currentPeriod;
            var S = this.SCORING;
            var roundScore = 0;
            var coachNotes = [];

            if (round === 1) {
                var s1 = S.sentenceFraming[d.sentenceFraming] || 0;
                var s2 = S.forkClarity[d.forkClarity] || 0;
                var s3 = S.killListSize[String(d.killListSize)] || 0;
                roundScore = s1 + s2 + s3;
                state.domainState.spineScore = roundScore;

                if (d.sentenceFraming === 'recap')    coachNotes.push('cn_sf_recap');
                if (d.sentenceFraming === 'compound') coachNotes.push('cn_sf_compound');
                if (d.sentenceFraming === 'vague')    coachNotes.push('cn_sf_vague');
                if (d.sentenceFraming === 'singular') coachNotes.push('cn_sf_singular');

                if (d.forkClarity === 'noFork')    coachNotes.push('cn_fork_none');
                if (d.forkClarity === 'softFork')  coachNotes.push('cn_fork_soft');
                if (d.forkClarity === 'namedFork') coachNotes.push('cn_fork_named');

                var k = parseInt(d.killListSize, 10);
                if (k < 4)              coachNotes.push('cn_kill_short');
                if (k >= 4 && k <= 6)   coachNotes.push('cn_kill_range');
                if (k > 6)              coachNotes.push('cn_kill_aggr');
            } else if (round === 2) {
                var t1 = S.slideHeadlines[d.slideHeadlines] || 0;
                var t2 = S.bodyDensity[String(d.bodyDensity)] || 0;
                var t3 = S.askPlacement[d.askPlacement] || 0;
                roundScore = t1 + t2 + t3;
                state.domainState.deckScore = roundScore;

                if (d.slideHeadlines === 'generic')     coachNotes.push('cn_head_generic');
                if (d.slideHeadlines === 'descriptive') coachNotes.push('cn_head_desc');
                if (d.slideHeadlines === 'billboard')   coachNotes.push('cn_head_bill');

                var w = parseInt(d.bodyDensity, 10);
                if (w >= 60)            coachNotes.push('cn_dens_high');
                if (w === 45)           coachNotes.push('cn_dens_45');
                if (w <= 30)            coachNotes.push('cn_dens_ok');

                if (d.askPlacement === 'none')     coachNotes.push('cn_ask_none');
                if (d.askPlacement === 'appendix') coachNotes.push('cn_ask_appendix');
                if (d.askPlacement === 'slide1')   coachNotes.push('cn_ask_s1');
                if (d.askPlacement === 'slide2')   coachNotes.push('cn_ask_s2');
                if (d.askPlacement === 'slide3')   coachNotes.push('cn_ask_s3');
            } else if (round === 3) {
                var u1 = S.openingStyle[d.openingStyle] || 0;
                var u2 = S.timingPlan[d.timingPlan] || 0;
                var u3 = S.askPhrasing[d.askPhrasing] || 0;
                var u4 = S.interruptionBridges[String(d.interruptionBridges)] || 0;
                roundScore = u1 + u2 + u3 + u4;
                state.domainState.deliveryScore = roundScore;

                if (d.openingStyle === 'thanksAgenda') coachNotes.push('cn_open_thanks');
                if (d.openingStyle === 'agendaOnly')   coachNotes.push('cn_open_agenda');
                if (d.openingStyle === 'storyHook')    coachNotes.push('cn_open_story');
                if (d.openingStyle === 'spineFirst')   coachNotes.push('cn_open_spine');

                if (d.timingPlan === '90-90-90')   coachNotes.push('cn_time_90');
                if (d.timingPlan === '40-60-140')  coachNotes.push('cn_time_40');
                if (d.timingPlan === '70-80-90')   coachNotes.push('cn_time_70');
                if (d.timingPlan === '80-80-80')   coachNotes.push('cn_time_80');
                if (d.timingPlan === '60-80-100')  coachNotes.push('cn_time_60');

                if (d.askPhrasing === 'subjunctive')      coachNotes.push('cn_phr_sub');
                if (d.askPhrasing === 'soft')             coachNotes.push('cn_phr_soft');
                if (d.askPhrasing === 'specificResource') coachNotes.push('cn_phr_spec');
                if (d.askPhrasing === 'decisionShaped')   coachNotes.push('cn_phr_dec');

                var b = parseInt(d.interruptionBridges, 10);
                if (b === 0) coachNotes.push('cn_br_0');
                if (b === 1) coachNotes.push('cn_br_1');
                if (b === 2) coachNotes.push('cn_br_2');
                if (b === 3) coachNotes.push('cn_br_3');
            }

            state.domainState.totalScore =
                (state.domainState.spineScore || 0)
                + (state.domainState.deckScore || 0)
                + (state.domainState.deliveryScore || 0);

            var maxScore = 390;
            var ratio = Math.max(0, state.domainState.totalScore / maxScore);
            var approval = Math.max(8, Math.min(72, Math.round(20 + ratio * 50)));
            state.domainState.approvalProb = approval;
            // platform score: approval probability (already 0 to 100), the same value getPerformanceSummary reports as overallScore
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(approval))) });

            state.domainState.spineHistory.push(state.domainState.spineScore);
            state.domainState.deckHistory.push(state.domainState.deckScore);
            state.domainState.deliveryHistory.push(state.domainState.deliveryScore);
            state.domainState.approvalHistory.push(approval);
            state.domainState.roundScoreHistory.push(roundScore);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1, domainState: state.domainState });
            }, 400);

            setTimeout(function() {
                var fb = document.getElementById('coachFeedback');
                var fbb = document.getElementById('coachFeedbackBody');
                if (fb && fbb) {
                    fb.style.display = 'block';
                    fbb.innerHTML = coachNotes.map(function(n) { return '• ' + window.mySimulation.t(n); }).join('<br>');
                }
            }, 100);

            return {
                period: state.currentPeriod,
                roundScore: roundScore,
                spineScore: state.domainState.spineScore,
                deckScore: state.domainState.deckScore,
                deliveryScore: state.domainState.deliveryScore,
                approvalProb: approval,
                coachSummary: coachNotes[0] ? window.mySimulation.t(coachNotes[0]) : '',
                coachSummaryKey: coachNotes[0] || ''
            };
        }

