        getPerformanceSummary(history) {
            if (!history.length) return {};
            var final = history[history.length - 1];
            var approval = (final.results && final.results.approvalProb) || 20;
            var t = function(k) { return window.mySimulation.t(k); };
            var ds = (window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var total = Math.round(ds.totalScore || 0);

            var band = 'beginner';
            if (approval >= 60) band = 'excellent';
            else if (approval >= 45) band = 'good';
            else if (approval >= 30) band = 'developing';

            var insights = [t('ins_' + band + '_1')];
            if (band === 'excellent') insights.push(t('ins_excellent_2'));

            return {
                approval: approval,
                approvalProb: approval,
                rawScore: total,
                outcome: t('outcome_' + band),
                performance: band,
                performanceKey: band,
                performanceLabel: t('perf_' + band),
                overallScore: approval,
                totalScore: approval,
                composite: approval,
                score: approval,
                maxScore: 100,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var esc = function(v) {
                return String(v === undefined || v === null ? '' : v)
                    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
            };
            var ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            return '<div class="exec-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="exec-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<p class="exec-debrief-outcome">' + esc(t('debrief_outcome')) + ' <strong>' +
                       esc(s.outcome || '') + '</strong></p>' +
                     '<div class="exec-debrief-insights">' + ins + '</div>' +
                   '</div>';
        }

