        _updateBriefing(state) {
            var idx = Math.min(Math.max((state.currentPeriod || 1) - 1, 0), this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var tr = function(key, fallback) {
                if (!window.mySimulation || !key) return fallback;
                var v = window.mySimulation.t(key);
                return (v && v !== key) ? v : fallback;
            };
            var finished = (state.currentPeriod || 1) > this.ROUNDS.length;

            var bt = document.getElementById('briefingTitle');
            if (bt) bt.innerHTML = finished ? tr('run_over_title', 'Run complete')
                                            : tr(round.titleKey, round.title);

            var bb = document.getElementById('briefingBody');
            if (bb) bb.innerHTML = finished ? tr('run_over_text', 'All rounds are in.')
                                            : tr(round.bodyKey, round.body);

            var hl = document.getElementById('hoursLeft');
            if (hl) hl.innerHTML = finished ? '' : tr(round.hoursKey, round.hours);

            ['round1Panel', 'round2Panel', 'round3Panel'].forEach(function(id, i) {
                var el = document.getElementById(id);
                if (el) el.style.display = (!finished && i === idx) ? 'block' : 'none';
            });

            var btnRow = document.getElementById('execButtonRow');
            if (btnRow) btnRow.style.display = finished ? 'none' : 'block';

            // NOTE: do not sync controls from decisions here. validateDecisions()
            // calls _updateBriefing() before reading the DOM, so writing stored
            // decisions back at this point would overwrite the player's choices.
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new StorytellingAdapter(), {
            simulationType: 'storytelling_for_exec',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

